import type { Question } from '../../lib/types'

export const ec2_compute_questions: Question[] = [
  { id: 'd3-ec2-001', domain: 3, topics: ['EC2', 'instance types', 'memory optimized'], type: 'single', stem: 'A company runs a high-performance in-memory database that requires 768 GB of RAM. Which EC2 instance family is most appropriate?', options: [{ id: 'A', text: 'C5 (compute optimized)' }, { id: 'B', text: 'R6i or X2idn (memory optimized) — highest memory-to-vCPU ratio in the EC2 family' }, { id: 'C', text: 'T3 (burstable)' }, { id: 'D', text: 'I3 (storage optimized)' }], correct: ['B'], explanation: 'R-class (memory optimized) instances provide up to 768 GB of RAM. X-class goes even higher (up to 24 TB). For memory-intensive workloads like SAP HANA, in-memory databases, and large caches, R/X families are the choice.', distractors: { A: 'C5 optimizes CPU-to-memory ratio — high vCPUs but lower memory per instance.', C: 'T3 is burstable general purpose — unsuitable for consistent high-memory requirements.', D: 'I3 is NVMe SSD storage optimized (I/O intensive) — not memory optimized.' } },
  { id: 'd3-ec2-002', domain: 3, topics: ['EC2', 'placement groups', 'cluster'], type: 'single', stem: 'An HPC application requires the lowest possible network latency and highest throughput between EC2 instances. Which placement group type achieves this?', options: [{ id: 'A', text: 'Spread placement group' }, { id: 'B', text: 'Partition placement group' }, { id: 'C', text: 'Cluster placement group — instances in the same AZ on the same physical rack, connected via high-bandwidth low-latency network' }, { id: 'D', text: 'No placement group — default placement is random' }], correct: ['C'], explanation: 'Cluster placement groups place instances on the same physical rack within an AZ, enabling 100 Gbps network bandwidth and single-digit microsecond latency. Ideal for HPC, MPI workloads, and tightly coupled applications.', distractors: { A: 'Spread placement groups place instances on separate physical hardware — maximizes fault tolerance but increases latency.', B: 'Partition groups distribute instances across separate server racks — good for large distributed systems but not minimal latency.', D: 'Default placement has no guarantees on physical proximity — higher latency than cluster.' } },
  { id: 'd3-ec2-003', domain: 3, topics: ['EC2', 'instance store', 'NVMe', 'performance'], type: 'single', stem: 'A big data processing job requires millions of IOPS and highest possible disk throughput. The data is temporary (can be regenerated). Which storage option provides maximum I/O performance?', options: [{ id: 'A', text: 'EBS io2 Block Express' }, { id: 'B', text: 'EC2 instance store (NVMe SSD) — physically attached storage with sub-millisecond latency, millions of IOPS' }, { id: 'C', text: 'EFS with max throughput mode' }, { id: 'D', text: 'EBS gp3 with max IOPS provisioned' }], correct: ['B'], explanation: 'Instance store (NVMe) is physically attached to the host server — no network hop. Provides lowest latency and highest throughput (millions of IOPS). Data is lost when the instance stops/terminates, making it suitable for temporary processing.', distractors: { A: 'EBS io2 Block Express provides up to 256,000 IOPS but has network latency vs. instance store.', C: 'EFS is a network file system — higher latency than local NVMe storage.', D: 'EBS gp3 up to 16,000 IOPS — much lower than instance store NVMe.' } },
  { id: 'd3-ec2-004', domain: 3, topics: ['EC2', 'Nitro', 'ENA', 'enhanced networking'], type: 'single', stem: 'A high-performance network application on EC2 requires higher bandwidth and lower latency than traditional virtualized networking. What EC2 feature provides this?', options: [{ id: 'A', text: 'Classic Elastic Network Interface' }, { id: 'B', text: 'Elastic Network Adapter (ENA) enhanced networking — provides up to 100 Gbps network bandwidth with lower CPU overhead' }, { id: 'C', text: 'Elastic Fabric Adapter (EFA)' }, { id: 'D', text: 'Public Elastic IP' }], correct: ['B'], explanation: 'ENA provides single root I/O virtualization (SR-IOV) for network acceleration. It bypasses the hypervisor for network I/O, delivering higher bandwidth (up to 100 Gbps), lower latency, and lower CPU overhead than traditional virtualization.', distractors: { A: 'Classic ENI uses slower virtual network drivers — not hardware accelerated.', C: 'EFA is specifically for HPC/MPI inter-node communication — not general network performance.', D: 'Elastic IP is a public IP allocation — not a network performance feature.' } },
  { id: 'd3-ec2-005', domain: 3, topics: ['EC2', 'EFA', 'HPC'], type: 'single', stem: 'An MPI (Message Passing Interface) application needs inter-node communication with ultra-low latency comparable to on-premises InfiniBand. What EC2 feature enables this?', options: [{ id: 'A', text: 'Elastic Network Adapter (ENA)' }, { id: 'B', text: 'Elastic Fabric Adapter (EFA) — OS-bypass capability for inter-node MPI communication with InfiniBand-like performance' }, { id: 'C', text: 'Cluster placement group alone' }, { id: 'D', text: 'Amazon CloudFront' }], correct: ['B'], explanation: 'EFA provides OS-bypass: MPI libraries communicate directly with the network hardware, skipping the OS kernel. This achieves latency comparable to InfiniBand. Required for HPC workloads using MPI/NCCL.', distractors: { A: 'ENA provides fast network I/O but still goes through the OS network stack — EFA bypasses it for MPI.', C: 'Cluster placement groups improve physical proximity and bandwidth — EFA specifically enables OS-bypass MPI communication.', D: 'CloudFront is a CDN — unrelated to HPC inter-node communication.' } },
  { id: 'd3-ec2-006', domain: 3, topics: ['EC2', 'burstable', 'T3', 'CPU credits'], type: 'single', stem: 'A T3 instance has been running at 100% CPU for several hours and performance has degraded significantly. What is the most likely cause?', options: [{ id: 'A', text: 'The instance is experiencing a hardware failure' }, { id: 'B', text: 'The instance has exhausted its CPU credits — T3 instances throttle to baseline performance when credits run out' }, { id: 'C', text: 'The EBS volume is the bottleneck' }, { id: 'D', text: 'Network latency is causing high CPU wait' }], correct: ['B'], explanation: 'T3 burstable instances accumulate CPU credits when below baseline, and spend them during bursts. When credits are exhausted, CPU is throttled to the baseline (e.g., 20-30%). Enable T3 Unlimited to avoid throttling (charges apply for sustained burst).', distractors: { A: 'Hardware failure would typically cause an instance to stop, not degrade.', C: 'EBS bottleneck appears as I/O wait, not general CPU throttling.', D: 'Network latency causes network wait — doesn\'t throttle CPU performance.' } },
  { id: 'd3-ec2-007', domain: 3, topics: ['EC2', 'Graviton', 'ARM', 'cost performance'], type: 'single', stem: 'A company wants to improve the price-performance ratio of their EC2 workloads. Their application is containerized and does not require Windows. Which processor architecture offers better price-performance?', options: [{ id: 'A', text: 'Intel Xeon (m5 instances)' }, { id: 'B', text: 'AMD EPYC (m5a instances)' }, { id: 'C', text: 'AWS Graviton (m7g) — ARM-based processor offering up to 40% better price-performance than x86 equivalents' }, { id: 'D', text: 'GPU instances (p4)' }], correct: ['C'], explanation: 'AWS Graviton3 (m7g, c7g, r7g) provides up to 40% better price-performance than comparable x86 instances. Supported by containerized workloads, Java, Python, Go, Node.js. Not suitable for Windows or x86-only native code.', distractors: { A: 'Intel instances are well-supported but higher cost for equivalent performance vs. Graviton.', B: 'AMD EPYC offers ~10% discount vs. Intel for similar performance — less savings than Graviton.', D: 'GPU instances are for ML training/inference, graphics rendering — not general application performance.' } },
  { id: 'd3-ec2-008', domain: 3, topics: ['EC2', 'Hibernate', 'RAM state'], type: 'single', stem: 'A company runs computationally expensive applications that take 30 minutes to initialize and load data into RAM. They want to stop instances overnight but resume instantly without the 30-minute initialization. What EC2 feature enables this?', options: [{ id: 'A', text: 'EC2 Stop/Start' }, { id: 'B', text: 'EC2 Hibernate — saves RAM state to EBS, restores on start; instance continues from where it stopped' }, { id: 'C', text: 'EC2 Reboot' }, { id: 'D', text: 'EC2 Standby' }], correct: ['B'], explanation: 'EC2 Hibernate saves the instance\'s RAM to the EBS root volume (encrypted). On resume, the instance restores from the saved state — processes continue, data is in memory. No re-initialization required.', distractors: { A: 'Stop/Start clears RAM — the instance boots fresh on start, requiring full re-initialization.', C: 'Reboot reboots the OS — no RAM state preservation.', D: 'EC2 Standby is an ASG state for removing an instance from the load balancer — not memory hibernation.' } },
  { id: 'd3-ec2-009', domain: 3, topics: ['EC2', 'dedicated hosts', 'dedicated instances'], type: 'single', stem: 'A company has per-socket SQL Server licensing that must run on dedicated physical servers — the license is tied to the physical CPU socket count. What EC2 option satisfies this?', options: [{ id: 'A', text: 'Dedicated Instance — runs on dedicated hardware but host is managed by AWS' }, { id: 'B', text: 'Dedicated Host — complete physical server dedicated to the account, with visibility into socket/core count for BYOL licensing' }, { id: 'C', text: 'Reserved Instance' }, { id: 'D', text: 'On-Demand Instance on isolated hardware' }], correct: ['B'], explanation: 'Dedicated Hosts provide a physical EC2 server for the account\'s exclusive use. The customer controls instance placement and can see the host\'s socket/core topology — essential for per-socket or per-core BYOL licensing (Windows Server, SQL Server, Oracle).', distractors: { A: 'Dedicated Instances run on dedicated hardware but AWS manages the host. No visibility into socket topology for BYOL licensing.', C: 'Reserved Instances are a pricing commitment — not an isolation or licensing compliance model.', D: 'On-Demand on isolated hardware is Dedicated Instance — not Dedicated Host.' } },
  { id: 'd3-ec2-010', domain: 3, topics: ['EC2', 'GPU', 'ML inference'], type: 'single', stem: 'A company needs to run real-time ML inference at scale with low latency. They want GPU-based acceleration. Which EC2 instance type is purpose-built for ML inference?', options: [{ id: 'A', text: 'P4d (ML training)' }, { id: 'B', text: 'Inf2 — AWS Inferentia2 chips purpose-built for high-performance low-cost ML inference' }, { id: 'C', text: 'G4dn — GPU for gaming and video' }, { id: 'D', text: 'C6i (compute optimized)' }], correct: ['B'], explanation: 'Inf2 instances use AWS Inferentia2 ASICs designed specifically for inference workloads. They provide high throughput, low latency inference at lower cost than GPU alternatives like P4. Also consider Inf1 for previous generation.', distractors: { A: 'P4d uses NVIDIA A100 GPUs optimized for training — not cost-efficient for inference.', C: 'G4dn uses NVIDIA T4 GPUs — primarily for graphics rendering and less cost-efficient for inference than Inf2.', D: 'C6i is general-purpose compute — doesn\'t provide accelerated ML inference.' } },
  { id: 'd3-ec2-011', domain: 3, topics: ['EC2', 'Spot Instances', 'interruption', 'strategy'], type: 'single', stem: 'A data analytics job uses EC2 Spot instances. To minimize the impact of Spot interruptions, which strategy should be implemented?', options: [{ id: 'A', text: 'Use only one instance type in one AZ for simplicity' }, { id: 'B', text: 'Use mixed instance types across multiple AZs with Spot Instance diversification — interruptions in one pool don\'t affect all instances' }, { id: 'C', text: 'Use Reserved Instances instead of Spot' }, { id: 'D', text: 'Set a very high bid price' }], correct: ['B'], explanation: 'Spot diversification across instance types and AZs (multiple Spot capacity pools) reduces interruption risk. If one pool is reclaimed, others remain. Use Spot Fleet with the price-capacity-optimized allocation strategy.', distractors: { A: 'Single instance type/AZ means all instances are in the same capacity pool — one interruption event affects all.', C: 'Reserved Instances cost more — the question asks about handling interruptions, not avoiding Spot.', D: 'Spot pricing is market-based; bidding above on-demand doesn\'t prevent interruption — capacity availability determines interruptions.' } },
  { id: 'd3-ec2-012', domain: 3, topics: ['EC2', 'EBS', 'io2', 'performance'], type: 'single', stem: 'A database requires 250,000 IOPS and 4000 MB/s throughput from EBS. Which EBS volume type meets these requirements?', options: [{ id: 'A', text: 'gp3 — max 16,000 IOPS' }, { id: 'B', text: 'io1 — max 64,000 IOPS' }, { id: 'C', text: 'io2 Block Express — up to 256,000 IOPS and 4000 MB/s throughput' }, { id: 'D', text: 'st1 — throughput optimized HDD' }], correct: ['C'], explanation: 'EBS io2 Block Express is the highest performance EBS volume: up to 256,000 IOPS, 4000 MB/s throughput, and sub-millisecond latency. Requires Nitro-based instances. Maximum 64,000 IOPS per instance without io2 BE (io1 cap), io2 BE raises this.', distractors: { A: 'gp3 maximum is 16,000 IOPS — far below 250,000 IOPS requirement.', B: 'io1 maximum is 64,000 IOPS per volume — far below 250,000 IOPS.', D: 'st1 is throughput-optimized HDD — low IOPS, not suitable for high-IOPS requirements.' } },
  { id: 'd3-ec2-013', domain: 3, topics: ['EC2', 'AMI', 'golden image', 'performance'], type: 'single', stem: 'A company needs EC2 instances to launch quickly with pre-installed software without installation delays. What approach minimizes launch time?', options: [{ id: 'A', text: 'Install software via user data script at launch' }, { id: 'B', text: 'Create a pre-baked AMI (golden image) with all software installed — launch instances from the AMI instantly' }, { id: 'C', text: 'Use AWS Systems Manager to install software after launch' }, { id: 'D', text: 'Use larger instance types to speed up installation' }], correct: ['B'], explanation: 'Golden AMIs (pre-baked images) contain all software pre-installed. Instances launch and are immediately ready — no installation time. Particularly important for Auto Scaling groups where new instances must be ready quickly.', distractors: { A: 'User data scripts run at every launch — installation time adds to the launch duration.', C: 'SSM configuration runs after launch — adds startup delay.', D: 'Larger instances have more resources — doesn\'t eliminate software installation time.' } },
  { id: 'd3-ec2-014', domain: 3, topics: ['EC2', 'Nitro Enclaves', 'sensitive data'], type: 'single', stem: 'An application processes highly sensitive cryptographic keys and PII. The processing must be isolated from the instance\'s own OS, hypervisor, and operators. What EC2 feature provides this secure environment?', options: [{ id: 'A', text: 'EC2 Dedicated Host' }, { id: 'B', text: 'EC2 Nitro Enclaves — isolated, cryptographic attestable compute environment running inside the EC2 instance' }, { id: 'C', text: 'EC2 instance with encrypted EBS' }, { id: 'D', text: 'AWS Secrets Manager' }], correct: ['B'], explanation: 'Nitro Enclaves provide an isolated virtual machine inside an EC2 instance with no persistent storage, no network access, and no interactive access. Cryptographic attestation verifies the enclave\'s identity. Ideal for processing sensitive keys/PII.', distractors: { A: 'Dedicated Host provides physical isolation from other customers — not from your own OS/operators.', C: 'Encrypted EBS protects data at rest — not processing isolation within the instance.', D: 'Secrets Manager stores secrets — doesn\'t provide isolated compute for sensitive data processing.' } },
  { id: 'd3-ec2-015', domain: 3, topics: ['EC2', 'capacity reservation', 'performance'], type: 'single', stem: 'A company needs guaranteed EC2 capacity in a specific AZ for a disaster recovery scenario. They want to ensure instances can launch even during high demand periods. What feature reserves capacity?', options: [{ id: 'A', text: 'Reserved Instances' }, { id: 'B', text: 'On-Demand Capacity Reservations — reserve EC2 capacity in a specific AZ regardless of usage' }, { id: 'C', text: 'Spot Instances' }, { id: 'D', text: 'Dedicated Hosts' }], correct: ['B'], explanation: 'On-Demand Capacity Reservations reserve EC2 capacity in a specific AZ without any commitment. The reserved capacity is guaranteed to be available when needed. Pay for reserved capacity whether or not instances are running.', distractors: { A: 'Reserved Instances provide pricing discounts and billing credits — they don\'t guarantee physical capacity in a specific AZ.', C: 'Spot capacity can be reclaimed at any time — not guaranteed for DR scenarios.', D: 'Dedicated Hosts reserve physical servers — more expensive and not necessary just for capacity reservation.' } },
  { id: 'd3-ec2-016', domain: 3, topics: ['EC2', 'bandwidth', 'network performance'], type: 'single', stem: 'An EC2 application requires maximum network bandwidth for transferring large datasets between instances in the same VPC. What should be verified to maximize bandwidth?', options: [{ id: 'A', text: 'All EC2 instances support maximum bandwidth regardless of instance size' }, { id: 'B', text: 'Use instances with enhanced networking (ENA) in the same cluster placement group — larger instances provide more bandwidth' }, { id: 'C', text: 'Use Elastic IP addresses for better bandwidth' }, { id: 'D', text: 'Enable public internet routing for better bandwidth' }], correct: ['B'], explanation: 'Network bandwidth scales with instance size. Larger instances (e.g., c5n.18xlarge, 100 Gbps) provide more bandwidth. Cluster placement groups + ENA maximize bandwidth and minimize latency between instances in the same AZ.', distractors: { A: 'Bandwidth is tied to instance size — small instances have limited bandwidth regardless.', C: 'Elastic IPs are public addresses — VPC-internal traffic doesn\'t benefit from public IPs.', D: 'Public internet routing is slower and adds latency vs. VPC-internal routing.' } },
  { id: 'd3-ec2-017', domain: 3, topics: ['EC2', 'bare metal', 'use cases'], type: 'single', stem: 'A company needs to run a hypervisor or kernel-level software that requires direct hardware access and cannot be virtualized within an EC2 instance. What option provides this?', options: [{ id: 'A', text: 't3 instance with enhanced networking' }, { id: 'B', text: 'EC2 bare metal instances — direct hardware access without a hypervisor layer' }, { id: 'C', text: 'AWS Lambda' }, { id: 'D', text: 'EC2 Dedicated Instance' }], correct: ['B'], explanation: 'EC2 bare metal instances provide direct access to the underlying physical server hardware, bypassing the hypervisor. Supports VMware Cloud on AWS, licensing requirements needing physical hardware visibility, and workloads that must run on bare metal.', distractors: { A: 't3 instances run on the Nitro hypervisor — not bare metal.', C: 'Lambda is serverless function execution — not bare metal.', D: 'Dedicated Instances run on dedicated hardware but still have a hypervisor layer.' } },
  { id: 'd3-ec2-018', domain: 3, topics: ['EC2', 'IMDSv2', 'security'], type: 'single', stem: 'A company wants to prevent SSRF (Server Side Request Forgery) attacks from accessing EC2 instance metadata to steal IAM credentials. What must be enforced?', options: [{ id: 'A', text: 'Disable the EC2 instance metadata service entirely' }, { id: 'B', text: 'Enforce IMDSv2 (Instance Metadata Service v2) — requires session-oriented PUT request to get a token first, preventing SSRF' }, { id: 'C', text: 'Use IAM policies to restrict metadata access' }, { id: 'D', text: 'Rotate IAM credentials every hour' }], correct: ['B'], explanation: 'IMDSv2 requires a PUT request to get a session token before any metadata request. SSRF attacks that use GET requests to the metadata IP (169.254.169.254) can\'t get a token — the token prevents unauthorized metadata access.', distractors: { A: 'Disabling IMDS breaks applications that rely on instance metadata (IAM role credentials, region, etc.).', C: 'IAM policies control API permissions, not direct HTTP calls to the metadata endpoint.', D: 'Credential rotation reduces the window of exposure but doesn\'t prevent SSRF metadata theft in the first place.' } },
  { id: 'd3-ec2-019', domain: 3, topics: ['EC2', 'storage optimized', 'I4i'], type: 'single', stem: 'A high-frequency trading application requires extremely low latency I/O for its local database cache. Which EC2 instance family is optimized for storage I/O with NVMe SSD?', options: [{ id: 'A', text: 'R6i (memory optimized)' }, { id: 'B', text: 'I4i (storage optimized) — high-performance NVMe SSD instance storage with sub-10ms latency' }, { id: 'C', text: 'G5 (GPU)' }, { id: 'D', text: 'M6g (general purpose)' }], correct: ['B'], explanation: 'I-family instances (I3, I4i) are purpose-built for I/O-intensive workloads: high-frequency trading, NoSQL databases, time-series databases. They feature local NVMe SSD storage with very high IOPS and low latency.', distractors: { A: 'R6i is memory-optimized — more RAM, not local NVMe storage.', C: 'G5 instances have NVIDIA A10G GPUs for ML/graphics — not storage optimization.', D: 'M6g is general-purpose ARM — not storage-optimized.' } },
  { id: 'd3-ec2-020', domain: 3, topics: ['EC2', 'pricing', 'savings plans', 'reserved'], type: 'single', stem: 'A company runs a fleet of EC2 instances that is expected to grow. They want the best discount with flexibility to change instance types and sizes as workloads evolve. What pricing model provides this?', options: [{ id: 'A', text: 'EC2 Standard Reserved Instances (1-year, specific instance type)' }, { id: 'B', text: 'Compute Savings Plans — apply to any EC2, Lambda, or Fargate compute; flexible instance family, size, OS, region' }, { id: 'C', text: 'EC2 Instance Savings Plans — specific instance family and region but flexible size/OS' }, { id: 'D', text: 'On-Demand pricing' }], correct: ['B'], explanation: 'Compute Savings Plans provide the most flexibility: any EC2 instance family, region, OS, tenancy, and also Lambda and Fargate. Discounts up to 66% vs. On-Demand. Best for evolving workloads where instance types change.', distractors: { A: 'Standard RIs lock to specific instance type, AZ, tenancy — least flexible but deepest discounts.', C: 'EC2 Instance Savings Plans lock to a specific instance family in a specific region — more flexible than RIs but less than Compute Savings Plans.', D: 'On-Demand has no discounts — most expensive.' } },
  { id: 'd3-ec2-021', domain: 3, topics: ['EC2', 'network interfaces', 'ENI'], type: 'single', stem: 'A developer needs an EC2 instance to have multiple network interfaces — one for public traffic and one for an internal management network. What enables multiple IPs/interfaces on one EC2 instance?', options: [{ id: 'A', text: 'Secondary Elastic IP addresses' }, { id: 'B', text: 'Multiple Elastic Network Interfaces (ENIs) — each with their own private IP, security group, and subnet' }, { id: 'C', text: 'EC2 Dual Stack' }, { id: 'D', text: 'VPC Peering' }], correct: ['B'], explanation: 'Multiple ENIs can be attached to an EC2 instance, each with their own IP address, MAC address, security group, and subnet assignment. Attach ENIs to different subnets to place an instance in multiple networks.', distractors: { A: 'Elastic IPs are public addresses — multiple Elastic IPs can be added but don\'t provide separate management network isolation.', C: 'Dual Stack enables IPv4 and IPv6 on one ENI — not separate network interfaces.', D: 'VPC Peering connects VPCs — not about multiple interfaces on one instance.' } },
  { id: 'd3-ec2-022', domain: 3, topics: ['EC2', 'user data', 'launch scripts'], type: 'single', stem: 'An EC2 instance should run a bootstrap script on first launch to configure software. When does User Data execute?', options: [{ id: 'A', text: 'User Data runs on every instance start (including stop/start)' }, { id: 'B', text: 'By default, User Data runs once at first launch only (during boot)' }, { id: 'C', text: 'User Data runs manually when triggered by the user' }, { id: 'D', text: 'User Data runs during AMI creation only' }], correct: ['B'], explanation: 'By default, EC2 User Data scripts run only once — during the first boot of the instance. This happens after the instance state becomes "running". To run on every boot, configure the cloud-init settings accordingly.', distractors: { A: 'By default, User Data runs once — cloud-init caches a "ran" marker. Modifying the cloud-init configuration can change this.', C: 'User Data runs automatically during boot — not manually triggered.', D: 'User Data runs at instance boot, not during AMI creation.' } },
  { id: 'd3-ec2-023', domain: 3, topics: ['EC2', 'status checks', 'instance check', 'system check'], type: 'single', stem: 'An EC2 instance fails its system status check. What does this indicate?', options: [{ id: 'A', text: 'The application is not running properly' }, { id: 'B', text: 'AWS infrastructure problem — networking, power, or hardware issue with the physical host' }, { id: 'C', text: 'The EBS volume has errors' }, { id: 'D', text: 'The operating system has crashed' }], correct: ['B'], explanation: 'System status checks (checked by AWS) verify the underlying physical host is functioning: network connectivity, power, hardware. Instance status checks (checked by the OS) verify the instance\'s own OS and applications are functioning.', distractors: { A: 'Application issues show in instance status checks or custom CloudWatch metrics — not system checks.', C: 'EBS errors appear as I/O errors within the OS — system status checks are infrastructure-level.', D: 'OS crash is an instance-level check failure — system checks are AWS infrastructure level.' } },
  { id: 'd3-ec2-024', domain: 3, topics: ['EC2', 'EBS', 'throughput', 'gp3'], type: 'single', stem: 'A workload requires both 10,000 IOPS and 500 MB/s throughput on a 500 GB EBS volume. Which EBS type satisfies both independently?', options: [{ id: 'A', text: 'gp2 — IOPS and throughput are both tied to volume size' }, { id: 'B', text: 'gp3 — independently configure IOPS (up to 16,000) and throughput (up to 1,000 MB/s) regardless of size' }, { id: 'C', text: 'st1 — high throughput HDD' }, { id: 'D', text: 'sc1 — cold HDD' }], correct: ['B'], explanation: 'gp3 allows independent configuration of IOPS (3,000-16,000) and throughput (125 MB/s to 1,000 MB/s) regardless of volume size. A 500 GB gp3 can have 10,000 IOPS and 500 MB/s throughput.', distractors: { A: 'gp2 ties IOPS to volume size (3 IOPS/GB) — a 500 GB gp2 gives only 1,500 IOPS.', C: 'st1 provides high throughput but only 500 IOPS — not 10,000.', D: 'sc1 is cold HDD for infrequent access — lowest IOPS and throughput.' } },
  { id: 'd3-ec2-025', domain: 3, topics: ['EC2', 'processor options', 'hyperthreading'], type: 'single', stem: 'A workload performs better with fewer vCPUs at higher clock speed rather than many hyperthreaded vCPUs. How can EC2 be configured to disable hyperthreading?', options: [{ id: 'A', text: 'Hyperthreading cannot be disabled on EC2' }, { id: 'B', text: 'Use EC2 CPU options to specify a lower thread count per core (1 thread per core instead of 2)' }, { id: 'C', text: 'Use a smaller instance type' }, { id: 'D', text: 'Enable EC2 dedicated host' }], correct: ['B'], explanation: 'EC2 CPU options allow configuring the number of vCPUs and threads per core. Setting threads per core to 1 effectively disables hyperthreading. Useful for HPC workloads and per-vCPU software licensing.', distractors: { A: 'Hyperthreading can be controlled via EC2 CPU options.', C: 'Smaller instance types have fewer cores — CPU options allow disabling hyperthreading on any instance size.', D: 'Dedicated Hosts provide physical isolation — not hyperthreading control (though you can use CPU options on dedicated hosts too).' } },
  { id: 'd3-ec2-026', domain: 3, topics: ['EC2', 'IOPS', 'initialization', 'pre-warming'], type: 'single', stem: 'A company restores an EBS volume from a snapshot. Initial I/O operations are slower than expected. What explains this?', options: [{ id: 'A', text: 'EBS volumes from snapshots require warm-up — blocks are lazy-loaded from S3; first access triggers the load' }, { id: 'B', text: 'The instance is the bottleneck' }, { id: 'C', text: 'KMS encryption is causing overhead' }, { id: 'D', text: 'The snapshot is in a different region' }], correct: ['A'], explanation: 'EBS volumes restored from snapshots are lazy-initialized — data is loaded from Amazon S3 as blocks are first accessed. This causes initial I/O latency. Pre-warm by reading all data at launch (e.g., dd command) to pull all blocks from S3 before production use.', distractors: { B: 'Instance performance is unrelated to EBS snapshot lazy loading.', C: 'KMS encryption has negligible overhead for EBS — not the cause of initial slowness.', D: 'Snapshots are regional — snapshot region doesn\'t affect restored volume performance.' } },
  { id: 'd3-ec2-027', domain: 3, topics: ['EC2', 'spot fleet', 'diversification'], type: 'single', stem: 'An application uses a Spot Fleet to run 100 instances. To minimize the chance of significant interruption, which allocation strategy should be selected?', options: [{ id: 'A', text: 'lowestPrice — always uses cheapest instances' }, { id: 'B', text: 'diversified — spread instances across all Spot pools (instance types and AZs) for maximum resilience' }, { id: 'C', text: 'capacityOptimized — launch from pools with highest available capacity' }, { id: 'D', text: 'capacityOptimizedPrioritized' }], correct: ['B'], explanation: 'diversified allocates instances across all pools evenly. If one pool is interrupted, only a fraction of instances are affected. This is the most resilient strategy for large fleets where availability matters more than cost.', distractors: { A: 'lowestPrice concentrates all instances in the cheapest pool — if that pool is reclaimed, all instances are interrupted.', C: 'capacityOptimized is best for avoiding interruptions on a per-launch basis — it doesn\'t distribute existing instances.', D: 'capacityOptimizedPrioritized is similar to capacityOptimized but respects priority ordering — not the same as distributing across pools.' } },
  { id: 'd3-ec2-028', domain: 3, topics: ['EC2', 'networking', 'jumbo frames'], type: 'single', stem: 'To improve network efficiency for large data transfers between EC2 instances within the same VPC, what network configuration should be enabled?', options: [{ id: 'A', text: 'Use smaller packets for faster transmission' }, { id: 'B', text: 'Enable jumbo frames (MTU 9001) — reduces overhead by fitting more data per packet' }, { id: 'C', text: 'Use public IP routing for better performance' }, { id: 'D', text: 'Add a NAT Gateway for efficient routing' }], correct: ['B'], explanation: 'Jumbo frames (MTU 9001 vs. standard 1500) reduce the number of packets needed for the same data transfer, decreasing CPU overhead and increasing throughput. Supported within a VPC and Direct Connect.', distractors: { A: 'Smaller packets increase overhead (more headers per byte of data) — larger packets are more efficient.', C: 'Public IP routing goes over the internet — VPC-internal routing is faster.', D: 'NAT Gateway adds a hop — it doesn\'t optimize jumbo frames or bandwidth.' } },
  { id: 'd3-ec2-029', domain: 3, topics: ['EC2', 'EBS Multi-Attach', 'shared storage'], type: 'single', stem: 'Multiple EC2 instances need to simultaneously read and write to the same EBS volume. Which EBS feature enables this?', options: [{ id: 'A', text: 'EBS Standard volumes support multi-attach by default' }, { id: 'B', text: 'EBS Multi-Attach (io1/io2 only) — attach one EBS volume to up to 16 instances in the same AZ' }, { id: 'C', text: 'EFS for shared file storage' }, { id: 'D', text: 'S3 as shared block storage' }], correct: ['B'], explanation: 'EBS Multi-Attach allows attaching io1/io2 volumes to up to 16 Nitro EC2 instances simultaneously within the same AZ. Applications must use cluster-aware file systems (like clustered databases) to handle concurrent writes correctly.', distractors: { A: 'Only io1 and io2 support Multi-Attach — not gp2/gp3/st1/sc1.', C: 'EFS provides NFS file storage (not block storage) — correct for shared file access but a different storage type.', D: 'S3 is object storage — not block-level storage that can replace EBS.' } },
  { id: 'd3-ec2-030', domain: 3, topics: ['EC2', 'launch templates', 'autoscaling'], type: 'single', stem: 'A company wants to standardize EC2 instance configuration (instance type, AMI, security groups, key pair) and reuse it across multiple Auto Scaling groups. What enables this reuse?', options: [{ id: 'A', text: 'EC2 Launch Configurations (deprecated)' }, { id: 'B', text: 'EC2 Launch Templates — versioned, shareable templates supporting multiple instance types for mixed instances' }, { id: 'C', text: 'CloudFormation stacks' }, { id: 'D', text: 'Systems Manager documents' }], correct: ['B'], explanation: 'EC2 Launch Templates support versioning, can specify multiple instance types for mixed instance groups, and support all newer EC2 features (T3 Unlimited, Dedicated Hosts, Spot settings). Preferred over deprecated Launch Configurations.', distractors: { A: 'Launch Configurations are deprecated — Launch Templates replace them with more features.', C: 'CloudFormation stacks deploy infrastructure but aren\'t the right mechanism for ASG instance configuration templates.', D: 'SSM documents are for operational automation — not EC2 launch configuration.' } },
  { id: 'd3-ec2-031', domain: 3, topics: ['EC2', 'Graviton', 'migration'], type: 'single', stem: 'A company wants to migrate their x86 EC2 Java application to Graviton (ARM) to reduce costs. What is the primary consideration for migration?', options: [{ id: 'A', text: 'Java applications cannot run on ARM processors' }, { id: 'B', text: 'Java is cross-platform — the JVM handles ARM/x86 differences; just recompile/rebuild container images for ARM and test' }, { id: 'C', text: 'Graviton supports x86 binaries natively' }, { id: 'D', text: 'ARM instances have no network connectivity' }], correct: ['B'], explanation: 'Java (JVM-based) applications are generally portable to Graviton with recompilation. The JVM translates bytecode to native ARM instructions. However, native libraries (JNI), compiled binaries, and x86 assembly code need ARM versions. Container images need to be rebuilt for linux/arm64.', distractors: { A: 'Java is specifically designed to be cross-platform — it runs on ARM via the JVM.', C: 'Graviton is ARM64 — it does NOT run x86 binaries natively (no x86 emulation).', D: 'ARM instances have full network connectivity — no difference from x86 instances.' } },
  { id: 'd3-ec2-032', domain: 3, topics: ['EC2', 'tenancy', 'VPC settings'], type: 'single', stem: 'A company\'s VPC is configured with dedicated tenancy. What is the impact on EC2 instances launched in this VPC?', options: [{ id: 'A', text: 'All EC2 instances in the VPC are free' }, { id: 'B', text: 'All instances launched in the VPC run on dedicated hardware — even if launched as shared tenancy, they become dedicated' }, { id: 'C', text: 'Only instances specifically launched as dedicated are isolated' }, { id: 'D', text: 'VPC tenancy affects only RDS, not EC2' }], correct: ['B'], explanation: 'A VPC with dedicated instance tenancy forces ALL instances launched into it to run on dedicated hardware, regardless of the instance-level tenancy setting. This is important for compliance but significantly increases costs.', distractors: { A: 'Dedicated tenancy increases costs — not free.', C: 'Instance-level dedicated settings are overridden by VPC-level dedicated tenancy.', D: 'VPC tenancy affects EC2 instances specifically — not RDS (RDS has its own dedicated options).' } },
  { id: 'd3-ec2-033', domain: 3, topics: ['EC2', 'state manager', 'fleet management'], type: 'single', stem: 'A company manages 500 EC2 instances and needs to ensure all have the latest security patches applied consistently. What AWS service automates patch management at scale?', options: [{ id: 'A', text: 'EC2 AMI updates' }, { id: 'B', text: 'AWS Systems Manager Patch Manager — automate patching across EC2 fleets with maintenance windows and compliance reporting' }, { id: 'C', text: 'CloudFormation rolling updates' }, { id: 'D', text: 'EC2 Auto Scaling group refresh' }], correct: ['B'], explanation: 'SSM Patch Manager applies OS patches across EC2 fleets automatically. Configure patch baselines (which patches to apply), maintenance windows (when to apply), and patch groups. Compliance dashboards show unpatched instances.', distractors: { A: 'AMI updates require replacing instances — not patching running instances.', C: 'CloudFormation rolling updates replace instances — not in-place OS patching.', D: 'Instance refresh rolls out new launch template versions — not OS-level patches.' } },
  { id: 'd3-ec2-034', domain: 3, topics: ['EC2', 'networking', 'bandwidth throttling'], type: 'single', stem: 'A developer notices that EC2 network bandwidth is heavily throttled on a t3.small instance even with ENA enabled. What is the most likely explanation?', options: [{ id: 'A', text: 'ENA is not supported on t3 instances' }, { id: 'B', text: 'Smaller EC2 instances have lower network bandwidth limits — bandwidth scales with instance size' }, { id: 'C', text: 'The security group is limiting bandwidth' }, { id: 'D', text: 'Multi-AZ routing is the bottleneck' }], correct: ['B'], explanation: 'EC2 network bandwidth is capped per instance size. t3.small is limited to ~5 Gbps while c5n.18xlarge gets 100 Gbps. To get more bandwidth, use a larger instance. ENA provides efficient hardware network access but the cap is set by instance size.', distractors: { A: 'ENA is supported on t3 instances.', C: 'Security groups control access (allow/deny) — they don\'t throttle bandwidth.', D: 'Multi-AZ routing has slightly higher latency but doesn\'t specifically throttle bandwidth.' } },
  { id: 'd3-ec2-035', domain: 3, topics: ['EC2', 'key pair', 'access'], type: 'single', stem: 'An EC2 Windows instance was launched without a key pair. How can an RDP password be retrieved?', options: [{ id: 'A', text: 'It is impossible to access the instance' }, { id: 'B', text: 'Use AWS Systems Manager Session Manager — provides browser-based RDP/shell without key pairs or open inbound ports' }, { id: 'C', text: 'Create a new key pair and attach it to the instance' }, { id: 'D', text: 'Reset the instance password via the EC2 console' }], correct: ['B'], explanation: 'SSM Session Manager provides access to EC2 instances without SSH/RDP key pairs or open ports. For Windows, SSM can start an RDP session through the console. The SSM Agent must be installed and the instance must have an IAM role with SSM permissions.', distractors: { A: 'SSM Session Manager enables access without key pairs — not impossible.', C: 'Key pairs cannot be attached to running instances.', D: 'EC2 console doesn\'t provide a direct password reset option for Windows instances.' } },
  { id: 'd3-ec2-036', domain: 3, topics: ['EC2', 'EBS', 'Multi-Attach', 'consistency'], type: 'single', stem: 'EBS Multi-Attach is used with a clustered database on multiple instances. What is the application responsible for when using Multi-Attach?', options: [{ id: 'A', text: 'Nothing — EBS Multi-Attach handles all concurrency' }, { id: 'B', text: 'Applications must use I/O fencing and cluster-aware file systems — EBS doesn\'t coordinate concurrent writes; data corruption is possible without it' }, { id: 'C', text: 'Implement distributed locking via SQS' }, { id: 'D', text: 'EBS Multi-Attach only allows one instance to write at a time automatically' }], correct: ['B'], explanation: 'EBS Multi-Attach provides the shared block device — it doesn\'t coordinate concurrent write access. Applications (like Oracle RAC) must implement I/O fencing and use cluster-aware file systems to prevent data corruption from concurrent uncoordinated writes.', distractors: { A: 'EBS Multi-Attach is the shared hardware — application must handle concurrent access coordination.', C: 'SQS distributed locking is not the standard approach — cluster-aware databases have built-in mechanisms.', D: 'Multi-Attach does NOT serialize writes — all attached instances can write simultaneously, which requires application-level coordination.' } },
  { id: 'd3-ec2-037', domain: 3, topics: ['EC2', 'autoscaling', 'scheduled scaling'], type: 'single', stem: 'An application consistently has high traffic every Monday at 9 AM when markets open. Current Target Tracking scaling lags by 5 minutes during the spike. How can the lag be eliminated?', options: [{ id: 'A', text: 'Increase Target Tracking sensitivity' }, { id: 'B', text: 'Add a Scheduled Scaling action to pre-provision capacity at 8:55 AM every Monday — instances are ready before the spike' }, { id: 'C', text: 'Use Predictive Scaling only' }, { id: 'D', text: 'Deploy more instance types' }], correct: ['B'], explanation: 'Scheduled scaling pre-provisions capacity at known times, eliminating the reactive lag of metric-based scaling. For predictable traffic patterns (market open, business hours), scheduled actions provision instances before demand arrives.', distractors: { A: 'Target Tracking sensitivity can be tuned but there\'s inherent latency in detecting load, waiting for scale-out to complete.', C: 'Predictive Scaling uses ML to anticipate load and scale proactively — a good alternative, but Scheduled Scaling is simpler for known times.', D: 'More instance types affect which instances are launched — don\'t eliminate scaling lag.' } },
  { id: 'd3-ec2-038', domain: 3, topics: ['EC2', 'Graviton', 'cost optimization'], type: 'single', stem: 'A company runs a containerized Python web application on C5 instances (x86). They want to reduce compute costs by 30-40% without changing the application code. What is the simplest path?', options: [{ id: 'A', text: 'Switch to Reserved Instances for C5' }, { id: 'B', text: 'Rebuild container images for ARM64 and migrate to C7g (Graviton3) — same vCPU/memory but lower price and often better performance' }, { id: 'C', text: 'Switch to Lambda' }, { id: 'D', text: 'Use Spot Instances for all containers' }], correct: ['B'], explanation: 'Graviton3 (C7g) provides up to 40% better price-performance than equivalent x86. Python runs natively on ARM. Rebuilding container images for linux/arm64 is straightforward. No code changes required.', distractors: { A: 'RIs for C5 provide ~30-40% discount but keep x86 costs — Graviton provides savings AND performance improvement.', C: 'Lambda requires re-architecting — not "no application code changes."', D: 'Spot Instances can be interrupted — not appropriate for customer-facing web apps without careful handling.' } },
  { id: 'd3-ec2-039', domain: 3, topics: ['EC2', 'instance metadata', 'tags'], type: 'single', stem: 'An EC2 instance needs to know its own tags (environment=prod, team=backend) at runtime without IAM API calls. What feature provides tag access via the metadata service?', options: [{ id: 'A', text: 'CloudFormation stack outputs' }, { id: 'B', text: 'EC2 instance tag metadata — tags can be accessible via the instance metadata service at 169.254.169.254/latest/meta-data/tags/instance/' }, { id: 'C', text: 'AWS CLI DescribeTags API' }, { id: 'D', text: 'Systems Manager Parameter Store' }], correct: ['B'], explanation: 'EC2 instance tags can be enabled for access via IMDS (instance metadata). With this enabled, the instance can read its own tags at /latest/meta-data/tags/instance/ without any IAM API calls.', distractors: { A: 'CloudFormation outputs are for stack-level data — not available via IMDS.', C: 'DescribeTags requires IAM permissions and an API call — IMDS tag access is simpler for self-identification.', D: 'Parameter Store requires IAM permissions and an API call — IMDS is a lightweight metadata service.' } },
  { id: 'd3-ec2-040', domain: 3, topics: ['EC2', 'spread placement', 'availability'], type: 'single', stem: 'An application has 7 critical EC2 instances that must each be on separate physical hardware to maximize fault isolation. Each AZ has a limit. Which placement group type enforces this?', options: [{ id: 'A', text: 'Cluster placement group' }, { id: 'B', text: 'Partition placement group' }, { id: 'C', text: 'Spread placement group — each instance runs on a separate rack with independent power and networking; max 7 per AZ' }, { id: 'D', text: 'No placement group needed' }], correct: ['C'], explanation: 'Spread placement groups place each instance on distinct underlying hardware (separate racks). Max 7 instances per AZ per spread group. If a rack fails, only one instance is affected. Suitable for small numbers of critical instances needing maximum isolation.', distractors: { A: 'Cluster placement groups concentrate instances in the same rack — minimum latency but maximum shared failure risk.', B: 'Partition groups are for large distributed systems (Hadoop, Kafka) — each partition has multiple instances sharing hardware, different from per-instance separation.', D: 'Default placement doesn\'t guarantee separate hardware for each instance.' } },
  { id: 'd3-ec2-041', domain: 3, topics: ['EC2', 'Trn1', 'ML training'], type: 'single', stem: 'A company needs to train large language models (LLMs) at the lowest cost on AWS. Which EC2 instance family is purpose-built for ML training?', options: [{ id: 'A', text: 'P4d (NVIDIA A100 GPUs)' }, { id: 'B', text: 'Trn1 — AWS Trainium chips purpose-built for ML training, up to 50% cost savings vs. GPU' }, { id: 'C', text: 'G5 (NVIDIA A10G)' }, { id: 'D', text: 'C7g (Graviton3)' }], correct: ['B'], explanation: 'Trn1 instances use AWS Trainium ASICs optimized for training deep learning models. Up to 50% lower cost than GPU-based training. For LLMs, Trn1 + Trainium provides the best price-performance for training workloads.', distractors: { A: 'P4d NVIDIA A100 GPUs are excellent for training but more expensive than Trn1.', C: 'G5 is primarily for inference and graphics — less suited for large-scale LLM training.', D: 'C7g is a general-purpose ARM compute instance — no ML acceleration.' } },
  { id: 'd3-ec2-042', domain: 3, topics: ['EC2', 'lifecycle hooks', 'ASG', 'graceful shutdown'], type: 'single', stem: 'When Auto Scaling terminates an EC2 instance, the instance immediately shuts down, interrupting in-flight requests. How can the instance complete current requests before shutdown?', options: [{ id: 'A', text: 'Increase the instance size' }, { id: 'B', text: 'Configure an ASG lifecycle hook on instance termination — instance goes to Terminating:Wait state to complete work before terminating' }, { id: 'C', text: 'Disable Auto Scaling' }, { id: 'D', text: 'Use deregistration delay on the load balancer' }], correct: ['D'], explanation: 'Deregistration delay (default 300 seconds) on the ALB/NLB allows the draining of in-flight requests before the instance is deregistered and terminated. The load balancer stops sending new requests but allows existing connections to complete.', distractors: { A: 'Instance size doesn\'t affect termination behavior.', B: 'Lifecycle hooks provide a wait period for custom logic (draining queues, cleanup) — but for in-flight HTTP requests, deregistration delay is the direct solution.', C: 'Disabling Auto Scaling loses elasticity — not a solution.' } },
  { id: 'd3-ec2-043', domain: 3, topics: ['EC2', 'c7i', 'latest generation'], type: 'single', stem: 'When selecting between older and newer generation EC2 instance types (e.g., C4 vs. C7i), what is the general guidance?', options: [{ id: 'A', text: 'Older generation instances are cheaper and should be preferred' }, { id: 'B', text: 'Newer generation instances provide better price-performance and should generally be preferred unless there\'s a specific reason to stay on older hardware' }, { id: 'C', text: 'Newer generation instances are always more expensive' }, { id: 'D', text: 'Generation doesn\'t affect performance — only instance size matters' }], correct: ['B'], explanation: 'Each EC2 generation typically brings better price-performance: newer CPU architectures, more memory per dollar, higher network bandwidth. C7i (7th gen Intel) vs. C4 (4th gen): better performance per vCPU at same or lower cost.', distractors: { A: 'Older generation instances may be cheaper in absolute price but have worse price-performance ratio.', C: 'Newer generation may have the same or lower price while delivering better performance.', D: 'Generation significantly affects clock speed, memory bandwidth, and network capabilities — not just size.' } },
  { id: 'd3-ec2-044', domain: 3, topics: ['EC2', 'EBS', 'snapshot', 'performance'], type: 'single', stem: 'A company creates daily EBS snapshots. They notice that snapshot creation takes longer for some volumes than others of the same size. What determines snapshot duration?', options: [{ id: 'A', text: 'Snapshot size is always the same as the volume size' }, { id: 'B', text: 'Snapshots are incremental — only changed blocks since the last snapshot are transferred; more changes = longer snapshot time' }, { id: 'C', text: 'Snapshot speed depends on the instance type' }, { id: 'D', text: 'Snapshots always take the same time regardless of data changes' }], correct: ['B'], explanation: 'EBS snapshots are incremental. The first snapshot copies all blocks. Subsequent snapshots only transfer changed (dirty) blocks. A volume with many changes since the last snapshot takes longer than one with few changes.', distractors: { A: 'Only the first snapshot is full-volume — incremental snapshots transfer only changed blocks.', C: 'Snapshot I/O happens at the EBS level — instance type doesn\'t directly affect snapshot speed.', D: 'Snapshot duration varies based on the amount of changed data since the last snapshot.' } },
  { id: 'd3-ec2-045', domain: 3, topics: ['EC2', 'SLA', 'availability'], type: 'single', stem: 'What is the EC2 SLA for instance availability?', options: [{ id: 'A', text: '99.0% per instance' }, { id: 'B', text: '99.99% per region' }, { id: 'C', text: '99.99% monthly uptime for each EC2 region' }, { id: 'D', text: '100% with Reserved Instances' }], correct: ['C'], explanation: 'AWS EC2 SLA guarantees 99.99% (four nines) monthly uptime for each EC2 region. This SLA covers the service availability — individual instance failures are not covered by the SLA, which is why multi-AZ architectures are needed.', distractors: { A: 'Individual instance availability is not the SLA metric — the SLA is for the service.', B: 'Per region is correct but the exact figure is 99.99% — important for exam.', D: 'Reserved Instances are a pricing commitment — they don\'t change the SLA or guarantee individual instance uptime.' } },
]
